// Fixed native MySQL 8.4 / MariaDB 11.4 filename protocol; independent native oracle for each.
// Evidence: evidence/engine-01/mysql/storage-encoding-oracle.json. No user data.
using System.Buffers.Binary;
namespace Verifier.Data;
internal static partial class InnoDbIdentifier
{
    private static readonly byte[] CompactStorageLetters=Convert.FromBase64String("");
    private static int StorageLetterCode(char c)
    {
        var index=c switch
        {
            >= '\u00c0' and < '\u0600'=>c-0x00c0,
            >= '\u1e00' and < '\u2000'=>1344+c-0x1e00,
            >= '\u2160' and < '\u2180'=>1856+c-0x2160,
            >= '\u24b0' and < '\u24f0'=>1888+c-0x24b0,
            >= '\uff20' and < '\uff60'=>1952+c-0xff20,
            _=>-1
        };
        return index<0?0:BinaryPrimitives.ReadUInt16LittleEndian(CompactStorageLetters.AsSpan(index*2,2));
    }
}
